function tplMax(spec){const c=tplEnrCap(spec);return c?c.tot:0}
// machines per set, set by set
function tplEnrFill(caps,n){const a=[];for(let s=0;s<caps.length;s++){const m=Math.min(caps[s],n);a.push(m);n-=m}return a}
