  const gin=Math.floor(der*cap/rmax+1e-9),gout=Math.floor(der*cap/rout+1e-9),nMax=Math.min(G.geom,gin,gout);
  return{ok:true,k,r,G,mk,cap,der,rin,rout,gin,gout,nMax};
